    (n AB B T lo : Z) (sb : byte) (s3v : word),
  (1 <= n <= 2^31)%Z -> (kHighShadowEnd < AB)%Z -> (AB + needed2 n <= 2^47)%Z ->
  rw_cells asegs m 0xfdb10 [C8 (Z_to_bv 64 0x10cc78)] -> rw_cells asegs m 0x10cc78 [C8 (Z_to_bv 64 SHB)] ->
  rw_cells asegs m (shad AB) [C1 sb] -> bv_unsigned sb <> 0%Z -> stk asegs m lo (bv_unsigned sp) ->
  mem_inv asegs m ->
  evt asegs (allocate_p2_exit sp gp tp F fc n AB B T (Z_to_bv 64 1) s3v (Z_to_bv 64 (AB + rz_size n + n)) m [] lo (fun _ => True))
    (MS (mkR ra sp gp tp t0 t1 t2 (Z_to_bv 64 1) (Z_to_bv 64 n) a0 a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 AB) s3v (Z_to_bv 64 (AB + rz_size n)) (Z_to_bv 64 (AB + rz_size n + -16))
